function calculateTaskMinutes(count) {
  let total = 0;
  for (let counter = 1; counter <= count; counter += 1) {
    total += counter * 2;
  }
  return total;
}

function sumTo(limit) {
  let total = 0;
  for (let number = 1; number <= limit; number += 1) {
    total += number;
  }
  return total;
}

function calculateSales(days, dailySales) {
  let total = 0;
  for (let day = 1; day <= days; day += 1) {
    total += dailySales;
  }
  return total;
}
